    private fun handleLogin() {
        val email = username.text.toString().trim()
        val pass = password.text.toString().trim()

        // Validation
        if (email.isEmpty()) {
            username.error = "Email is required"
            username.requestFocus()
            return
        }

        if (pass.isEmpty()) {
            password.error = "Password is required"
            password.requestFocus()
            return
        }

        // Disable button and show loading
        actionButton.isEnabled = false
        actionButton.text = "Logging in..."

        // Make API call
        lifecycleScope.launch {
            try {
                val request = LoginRequest(email, pass)
                val response = RetrofitClient.apiService.login(request)

                if (response.isSuccessful && response.body()?.success == true) {
                    val authData = response.body()?.data

                    if (authData != null) {
                        // Save token and user data
                        tokenManager.saveAuthData(
                            token = authData.token,
                            userId = authData.user.id.toString(),
                            userName = authData.user.fullName,
                            userEmail = authData.user.email
                        )

                        // Get FCM token and send to backend
                        sendFcmTokenToBackend()

                        Toast.makeText(
                            this@LoginSignup,
                            "Login successful! Welcome ${authData.user.fullName}",
                            Toast.LENGTH_SHORT
                        ).show()

                        // Navigate to Home
                        navigateToHome()
                    }
                } else {
                    val errorMsg = response.body()?.message ?: "Login failed. Please check your credentials."
                    Toast.makeText(this@LoginSignup, errorMsg, Toast.LENGTH_LONG).show()

                    // Re-enable button
                    actionButton.isEnabled = true
                    actionButton.text = "Login"
                }
            } catch (e: Exception) {
                Toast.makeText(
                    this@LoginSignup,
                    "Network error: ${e.message}. Please check your connection.",
                    Toast.LENGTH_LONG
                ).show()

                // Re-enable button
                actionButton.isEnabled = true
                actionButton.text = "Login"
            }
        }
    }

    private fun handleSignup() {
        val name = fullName.text.toString().trim()
        val email = username.text.toString().trim()
        val studId = studentId.text.toString().trim()
        val batchVal = batch.text.toString().trim()
        val dept = department.text.toString().trim()
        val sect = section.text.toString().trim()
        val pass = password.text.toString().trim()

        // Validation
        if (name.isEmpty()) {
            fullName.error = "Full name is required"
            fullName.requestFocus()
            return
        }

        if (email.isEmpty()) {
            username.error = "Email is required"
            username.requestFocus()
            return
        }

        if (studId.isEmpty()) {
            studentId.error = "Student ID is required"
            studentId.requestFocus()
            return
        }

        if (batchVal.isEmpty()) {
            batch.error = "Batch is required"
            batch.requestFocus()
            return
        }

        if (dept.isEmpty()) {
            department.error = "Department is required"
            department.requestFocus()
            return
        }

        if (sect.isEmpty()) {
            section.error = "Section is required"
            section.requestFocus()
            return
        }

        if (pass.isEmpty() || pass.length < 6) {
            password.error = "Password must be at least 6 characters"
            password.requestFocus()
            return
        }

        // Disable button and show loading
        actionButton.isEnabled = false
        actionButton.text = "Creating account..."

        // Make API call
        lifecycleScope.launch {
            try {
                val request = SignupRequest(
                    fullName = name,
                    email = email,
                    password = pass,
                    studentId = studId,
                    batch = batchVal,
                    department = dept,
                    section = sect
                )

                val response = RetrofitClient.apiService.signup(request)

                if (response.isSuccessful && response.body()?.success == true) {
                    val authData = response.body()?.data

                    if (authData != null) {
                        // Save token and user data
                        tokenManager.saveAuthData(
                            token = authData.token,
                            userId = authData.user.id.toString(),
                            userName = authData.user.fullName,
                            userEmail = authData.user.email
                        )

                        // Get FCM token and send to backend
                        sendFcmTokenToBackend()

                        Toast.makeText(
                            this@LoginSignup,
                            "Account created successfully! Welcome ${authData.user.fullName}",
                            Toast.LENGTH_SHORT
                        ).show()

                        // Navigate to Home
                        navigateToHome()
                    }
                } else {
                    val errorMsg = response.body()?.message ?: "Signup failed. Please try again."
                    Toast.makeText(this@LoginSignup, errorMsg, Toast.LENGTH_LONG).show()

                    // Re-enable button
                    actionButton.isEnabled = true
                    actionButton.text = "Create Account"
                }
            } catch (e: Exception) {
                Toast.makeText(
                    this@LoginSignup,
                    "Network error: ${e.message}. Please check your connection.",
                    Toast.LENGTH_LONG
                ).show()

                // Re-enable button
                actionButton.isEnabled = true
                actionButton.text = "Create Account"
            }
        }
    }

    private fun sendFcmTokenToBackend() {
        FirebaseMessaging.getInstance().token.addOnCompleteListener { task ->
            if (task.isSuccessful) {
                val fcmToken = task.result
                Log.d("LoginSignup", "FCM Token: $fcmToken")

                lifecycleScope.launch {
                    try {
                        val token = tokenManager.getToken()
                        if (!token.isNullOrEmpty()) {
                            val authHeader = "Bearer $token"
                            val request = UpdateFcmTokenRequest(fcmToken)
                            val response = RetrofitClient.apiService.updateFcmToken(authHeader, request)

                            if (response.isSuccessful) {
                                Log.d("LoginSignup", "✅ FCM token sent to backend")
                            } else {
                                Log.e("LoginSignup", "❌ Failed to send FCM token: ${response.code()}")
                            }
                        }
                    } catch (e: Exception) {
                        Log.e("LoginSignup", "❌ Error sending FCM token", e)
                    }
                }
            } else {
                Log.e("LoginSignup", "❌ Failed to get FCM token", task.exception)
            }
        }
    }

    private fun navigateToHome() {
        val intent = Intent(this, Home::class.java)
        startActivity(intent)
        finish() // Close login screen so user can't go back
    }
}

package com.mustafafaraz.locateme

import android.os.Bundle
import android.view.View
import android.widget.ArrayAdapter
import android.widget.Button
import android.widget.EditText
import android.widget.ImageView
import android.widget.Spinner
import android.widget.TextView
import androidx.appcompat.app.AppCompatActivity
import androidx.core.content.ContextCompat

class ReportItem : AppCompatActivity() {

    private lateinit var toggleLost: TextView
    private lateinit var toggleFound: TextView
    private lateinit var locationLabel: TextView
    private lateinit var reportButton: Button

    private lateinit var itemTitle: EditText
    private lateinit var itemCategory: Spinner
    private lateinit var itemDescription: EditText
    private lateinit var itemLocation: Spinner
    private lateinit var contactMethod: EditText
    private lateinit var contactInfo: EditText

    private var isLostItem = true

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_report_item)

        initializeViews()
        setupToggleListeners()
        setupSpinners()
        setupClickListeners()
    }

    private fun initializeViews() {
        toggleLost = findViewById(R.id.toggle_lost)
        toggleFound = findViewById(R.id.toggle_found)
        locationLabel = findViewById(R.id.location_label)
        reportButton = findViewById(R.id.report_button)

        itemTitle = findViewById(R.id.item_title)
        itemCategory = findViewById(R.id.item_category)
        itemDescription = findViewById(R.id.item_description)
        itemLocation = findViewById(R.id.item_location)
        contactMethod = findViewById(R.id.contact_method)
        contactInfo = findViewById(R.id.contact_info)
    }

    private fun setupToggleListeners() {
        toggleLost.setOnClickListener {
            if (!isLostItem) {
                switchToLost()
            }
        }

        toggleFound.setOnClickListener {
            if (isLostItem) {
                switchToFound()
            }
        }
    }

    private fun setupSpinners() {
        // Category Spinner
        val categories = arrayOf(
            "Select Category",
            "Electronics",
            "Bags",
            "Keys",
            "Clothing",
            "Books",
            "Accessories",
            "Other"
        )
        val categoryAdapter = ArrayAdapter(this, android.R.layout.simple_spinner_item, categories)
        categoryAdapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item)
        itemCategory.adapter = categoryAdapter

        // Location Spinner
        val locations = arrayOf(
            "Select Location",
            "Library - 1st floor",
            "Library - 2nd floor",
            "Library - 3rd floor",
            "Cafeteria",
            "Main Building",
            "Lab Block",
            "Sports Complex",
            "Parking Area",
            "Other"
        )
        val locationAdapter = ArrayAdapter(this, android.R.layout.simple_spinner_item, locations)
        locationAdapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item)
        itemLocation.adapter = locationAdapter
    }

    private fun setupClickListeners() {
        // Back button
        findViewById<ImageView>(R.id.back_button).setOnClickListener {
            finish()
        }

        // Report button
        reportButton.setOnClickListener {
            handleReportSubmit()
        }

        // Add photo button
        findViewById<View>(R.id.add_photo_button).setOnClickListener {
            // TODO: Implement photo picker
        }

        // Bottom navigation
        findViewById<View>(R.id.nav_search).setOnClickListener {
            // TODO: Navigate to search/home
        }

        findViewById<View>(R.id.nav_report).setOnClickListener {
            // Already on report screen
        }

        findViewById<View>(R.id.nav_profile).setOnClickListener {
            // TODO: Navigate to profile
        }
    }

    private fun switchToLost() {
        isLostItem = true

        // Update toggle buttons
        toggleLost.setBackgroundResource(R.drawable.selected_button_login_signup)
        toggleLost.setTextColor(ContextCompat.getColor(this, R.color.black))

        toggleFound.background = null
        toggleFound.setTextColor(ContextCompat.getColor(this, R.color.black))

        // Update text labels
        locationLabel.text = "Where did you lose it? *"
        reportButton.text = "Report Lost Item"
    }

    private fun switchToFound() {
        isLostItem = false

        // Update toggle buttons
        toggleLost.background = null
        toggleLost.setTextColor(ContextCompat.getColor(this, R.color.black))

        toggleFound.setBackgroundResource(R.drawable.selected_button_login_signup)
        toggleFound.setTextColor(ContextCompat.getColor(this, R.color.black))

        // Update text labels
        locationLabel.text = "Where did you find it? *"
        reportButton.text = "Report Found Item"
    }

    private fun handleReportSubmit() {
        val title = itemTitle.text.toString()
        val category = itemCategory.selectedItem.toString()
        val description = itemDescription.text.toString()
        val location = itemLocation.selectedItem.toString()
        val method = contactMethod.text.toString()
        val contact = contactInfo.text.toString()

        // Validation
        if (title.isEmpty()) {
            itemTitle.error = "Please enter item title"
            return
        }

        if (category == "Select Category") {
            // Show error for category
            return
        }

        if (description.isEmpty()) {
            itemDescription.error = "Please enter description"
            return
        }

        if (location == "Select Location") {
            // Show error for location
            return
        }

        if (method.isEmpty()) {
            contactMethod.error = "Please enter contact method"
            return
        }

        if (contact.isEmpty()) {
            contactInfo.error = "Please enter contact information"
            return
        }

        // TODO: Submit the report to backend/database
        val itemType = if (isLostItem) "Lost" else "Found"

        // For now, just finish the activity
        finish()
    }
}

package com.mustafafaraz.locateme.data.api

import com.mustafafaraz.locateme.data.model.*
